'use client'

import { useRef, useState, type ComponentProps } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import { Avatar } from '../../atomic-elements/Avatar'
import { Button } from '../../buttons/Button'
import { LineChart } from '../../charts/LineChart'
import { Sparkline } from '../../charts/Sparkline'
import { Checkbox } from '../../controls/Checkbox'
import { Card } from '../../data-display/Card'
import { Select } from '../../inputs/Select'
import { ProgressBar } from '../../loaders/ProgressBar'
import { Link } from '../../navigation/Link'
import { Menu } from '../../navigation/Menu'
import { ActionPanel } from '../../patterns/application-ui/ActionPanel'
import { CardHeading } from '../../patterns/application-ui/CardHeading'
import { NavSidebar } from '../../patterns/application-ui/NavSidebar'
import { Stats, type Stat, type StatChange } from '../../patterns/application-ui/Stats'
import { TopBar } from '../../patterns/application-ui/TopBar'
import { EmptyState } from '../../states/EmptyState'
import { ActivityTimeline, money, type ActivityEvent } from '../object-management/ProjectActivity'
import { sampleProjects } from '../object-management/projects-data'
import { AppShell } from './AppShell'
import { PERIODS, sampleDays, sampleSetup, sampleTasks, sampleToday, type Period, type SetupStep, type Task } from './home-data'
import styles from './Home.module.css'

/** Who is signed in, in this sample. */
const ME = { name: 'Ines Okafor', initials: 'IO' }
const longDay = new Intl.DateTimeFormat('en', { weekday: 'long', day: 'numeric', month: 'long' })
const shortDay = new Intl.DateTimeFormat('en', { day: 'numeric', month: 'short' })
const count = new Intl.NumberFormat('en')

const greeting = (at: Date) => (at.getHours() < 12 ? 'Good morning' : at.getHours() < 18 ? 'Good afternoon' : 'Good evening')
const startOfDay = (at: Date) => new Date(at.getFullYear(), at.getMonth(), at.getDate()).getTime()

/** The change from one period's total to the one before, as Stats shows it; none when there is nothing to compare with. */
function change(now: number, before: number): StatChange | undefined {
  if (!before) return undefined
  const ratio = now / before - 1
  return { value: `${Math.abs(Math.round(ratio * 100))}%`, direction: ratio < 0 ? 'down' : 'up' }
}

/** The newest events across every project, each naming its project. */
const recentActivity: ActivityEvent[] = sampleProjects
  .flatMap((p) => p.activity.map((event) => ({ ...event, project: p.name })))
  .sort((a, b) => b.at.getTime() - a.at.getTime())
  .slice(0, 6)

export interface HomeProps extends Omit<ComponentProps<'div'>, 'children'> {
  /** Today, for the greeting and what is due. Defaults to the sample's day so the page holds still; pass `new Date()` in an app. */
  today?: Date
  /** The period the figures and the chart cover first. */
  defaultPeriod?: Period
  /** The signed-in user's tasks when the page opens; ticking them is local. Empty shows "Nothing due". */
  defaultTasks?: Task[]
  /** The setup guide's steps when the page opens. Hidden when empty or when every step is done. */
  defaultSetupSteps?: SetupStep[]
  /** Called when a task is ticked or unticked. Replace with a call to your API. */
  onTaskChange?: (id: string, isDone: boolean) => void
  /** Called with the step the setup guide's button does. Open your flow for it there. */
  onSetupStep?: (id: string) => void
}

/**
 * The home page: a greeting with a period to look at, the key figures for
 * it, a chart and the user's tasks in a grid of cards, recent activity
 * across projects in the aside, and a setup guide until the workspace is
 * set up. The state is local; swap the samples for your data layer when
 * you copy the page.
 */
export function Home({
  today = sampleToday,
  defaultPeriod = '30d',
  defaultTasks = sampleTasks,
  defaultSetupSteps = sampleSetup,
  onTaskChange,
  onSetupStep,
  ...props
}: HomeProps) {
  const [period, setPeriod] = useState(defaultPeriod)
  const [tasks, setTasks] = useState(defaultTasks)
  const [setup, setSetup] = useState(defaultSetupSteps)
  const titleRef = useRef<HTMLHeadingElement>(null)

  const { label: periodLabel, days } = PERIODS.find((p) => p.value === period) ?? PERIODS[1]
  const current = sampleDays.slice(-days)
  const before = sampleDays.slice(-2 * days, -days)
  const sum = (rows: typeof current, key: 'hours' | 'invoiced') => rows.reduce((total, row) => total + row[key], 0)
  const hours = { now: sum(current, 'hours'), before: sum(before, 'hours') }
  const invoiced = { now: sum(current, 'invoiced'), before: sum(before, 'invoiced') }
  const active = sampleProjects.filter((p) => p.status === 'Active' && !p.isArchived)
  const atRisk = active.filter((p) => p.health === 'risk' || p.health === 'potential-risk').length

  const stats: Stat[] = [
    {
      label: 'Hours logged',
      value: count.format(hours.now),
      previous: `from ${count.format(hours.before)}`,
      change: change(hours.now, hours.before),
      chart: <Sparkline data={current.map((d) => d.hours)} />,
    },
    {
      label: 'Invoiced',
      value: money.format(invoiced.now),
      previous: `from ${money.format(invoiced.before)}`,
      change: change(invoiced.now, invoiced.before),
      chart: <Sparkline data={current.map((d) => d.invoiced)} color="chart-2" />,
    },
    // A count as it stands now: the period does not apply to it.
    { label: 'Active projects', value: active.length, previous: `${atRisk} at risk`, href: '#projects', linkLabel: 'View projects' },
  ]

  const nextStep = setup.find((s) => !s.isDone)
  const doneSteps = setup.filter((s) => s.isDone).length
  const openTasks = tasks.filter((t) => !t.isDone).length
  const todayStart = startOfDay(today)

  const account = (
    <div className={styles.account}>
      <Menu
        align="start"
        trigger={
          <Button variant="secondary" appearance="ghost" startIcon={<Avatar initials={ME.initials} size="sm" />}>
            {ME.name}
          </Button>
        }
        items={[{ label: 'Your profile' }, { label: 'Settings' }, { type: 'separator' }, { label: 'Sign out' }]}
      />
    </div>
  )

  return (
    <AppShell
      brand={<strong className={styles.brand}>Zweihänder</strong>}
      sidebar={
        <NavSidebar
          items={[
            { label: 'Dashboard', href: '#dashboard', icon: <Icon name="star" /> },
            { label: 'Projects', href: '#projects', icon: <Icon name="file" /> },
            { label: 'Team', href: '#team', icon: <Icon name="user" /> },
            { label: 'Calendar', href: '#calendar', icon: <Icon name="calendar" /> },
          ]}
          currentHref="#dashboard"
          className={styles.sidebar}
          footer={account}
        />
      }
      header={<TopBar end={account} />}
      aside={
        // The aside is the landmark named "Recent activity"; the timeline inside it takes no name of its own.
        <div className={styles.asideSection}>
          <h2 className={styles.sectionTitle}>Recent activity</h2>
          <ActivityTimeline events={recentActivity} />
        </div>
      }
      asideLabel="Recent activity"
      {...props}
    >
      <div className={styles.page}>
        <div className={styles.header}>
          <div className={styles.heading}>
            {/* Focusable from code only: it takes focus when the setup guide it sat above goes away. */}
            <h1 ref={titleRef} tabIndex={-1} className={styles.title}>
              {greeting(today)}, {ME.name.split(' ')[0]}
            </h1>
            <p className={styles.description}>
              <time dateTime={today.toLocaleDateString('en-CA') /* YYYY-MM-DD, in local time */}>{longDay.format(today)}</time>
            </p>
          </div>
          <Select
            label="Period"
            options={PERIODS.map(({ value, label }) => ({ value, label }))}
            value={period}
            onValueChange={(next) => next && setPeriod(next as Period)}
          />
        </div>

        {nextStep && (
          <ActionPanel
            title="Finish setting up"
            description={
              <div className={styles.setup}>
                <ProgressBar value={doneSteps} max={setup.length} label={`${doneSteps} of ${setup.length} steps done`} />
                <ol className={styles.steps}>
                  {setup.map((step) => (
                    <li key={step.id} className={cn(styles.step, step.isDone && styles.stepDone)}>
                      <Icon name={step.isDone ? 'success-filled' : 'minus'} aria-hidden="true" />
                      {step.label}
                      {step.isDone && <span className={styles.srOnly}> (done)</span>}
                    </li>
                  ))}
                </ol>
              </div>
            }
            actionPlacement="end"
            action={
              <Button
                onClick={() => {
                  // The sample marks the step done; an app opens the flow for it and marks it done when that finishes.
                  const next = setup.map((s) => (s.id === nextStep.id ? { ...s, isDone: true } : s))
                  setSetup(next)
                  onSetupStep?.(nextStep.id)
                  // The guide goes once the last step is done: focus moves to the page's heading, not to the body.
                  if (next.every((s) => s.isDone)) requestAnimationFrame(() => titleRef.current?.focus())
                }}
              >
                {nextStep.action}
              </Button>
            }
          />
        )}

        <Stats stats={stats} aria-label={`Key figures, ${periodLabel.toLowerCase()}`} />

        <div className={styles.grid}>
          <Card appearance="outline" className={styles.card}>
            <CardHeading
              title="Hours logged"
              description={periodLabel}
              actions={
                <Link href="#timesheets" size="sm" underline="hover">
                  Timesheets
                </Link>
              }
            />
            <LineChart title="Hours per day" data={current} x="date" series={[{ key: 'hours', label: 'Hours' }]} height={220} />
          </Card>

          <Card appearance="outline" className={styles.card}>
            <CardHeading title="Your tasks" description={openTasks === 1 ? '1 open' : `${openTasks} open`} />
            {tasks.length ? (
              <ul className={styles.tasks} aria-label="Your tasks">
                {tasks.map((task) => {
                  const due = startOfDay(task.due)
                  const isOverdue = !task.isDone && due < todayStart
                  const when = task.isDone ? 'Done' : isOverdue ? 'Overdue' : due === todayStart ? 'Due today' : `Due ${shortDay.format(task.due)}`
                  return (
                    <li key={task.id} className={cn(task.isDone && styles.taskDone)}>
                      <Checkbox
                        label={task.title}
                        helperText={
                          <>
                            {task.project} ·{' '}
                            <span className={cn(isOverdue && styles.overdue)}>{when}</span>
                          </>
                        }
                        checked={task.isDone}
                        onCheckedChange={(isDone) => {
                          setTasks((all) => all.map((t) => (t.id === task.id ? { ...t, isDone } : t)))
                          onTaskChange?.(task.id, isDone)
                        }}
                      />
                    </li>
                  )
                })}
              </ul>
            ) : (
              <EmptyState size="sm" headingLevel={3} title="Nothing due" description="Tasks assigned to you show here." />
            )}
          </Card>
        </div>
      </div>
    </AppShell>
  )
}

/* The page is the container: the cards sit side by side when the page is
   wide enough, whatever the viewport or the shell around it. */
.page {
  display: grid;
  gap: var(--space-section);
  container-type: inline-size;
}

/* Grid items keep their content's width by default; the chart must follow
   the column instead of widening the page. */
.page > * {
  min-inline-size: 0;
}

.brand {
  font-size: var(--text-heading-xs);
}

.sidebar {
  block-size: 100%;
}

.account {
  display: flex;
  align-items: center;
}

/* Greeting and period share a row while there is room; the period drops
   under the greeting when there is not. */
.header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-cluster) var(--space-group);
}

.heading {
  display: grid;
  gap: var(--space-2);
}

.title {
  margin: 0;
  font-family: var(--font-heading);
  font-size: var(--text-heading-xl);
  line-height: var(--leading-heading-xl);
  font-weight: 500;
  color: var(--foreground);
  outline: none;
}

.description {
  margin: 0;
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--muted-foreground);
}

.setup {
  display: grid;
  gap: var(--space-stack);
}

.steps {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-group);
  margin: 0;
  padding: 0;
  list-style: none;
}

.step {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

.stepDone svg {
  color: var(--success-text);
}

/* One column on a phone; side by side from 40rem, which a desktop page
   still has with the sidebar and the aside both open (about 46rem). The
   chart gets the larger share: its axis needs the width more than the
   tasks do. */
.grid {
  display: grid;
  gap: var(--space-group);
  align-items: start;
}
@container (min-width: 40rem) {
  .grid {
    grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  }
}

.card {
  display: grid;
  gap: var(--space-group);
  min-inline-size: 0;
}

.tasks {
  display: grid;
  gap: var(--space-stack);
  margin: 0;
  padding: 0;
  list-style: none;
}

/* A ticked task stays in the list, so a slip of the finger can be undone. */
.taskDone {
  color: var(--muted-foreground);
  text-decoration: line-through;
}

.overdue {
  color: var(--danger-text);
}

.asideSection {
  display: grid;
  gap: var(--space-group);
}

.sectionTitle {
  margin: 0;
  font-size: var(--text-heading-sm);
  line-height: var(--leading-heading-sm);
  font-weight: 600;
  color: var(--foreground);
}

.srOnly {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Sample data for the Home template. Every name is made up, and the numbers
   are seeded so tests and screenshots see the same page every run. Replace
   it with your own source; the page only needs the shapes below. */

// A bare date would parse as UTC midnight, the day before west of Greenwich.
const d = (iso: string) => new Date(`${iso}T00:00`)

/** "Today" in the sample, so the greeting, due dates and periods hold still. Pass `new Date()` in an app. */
export const sampleToday = new Date('2026-10-01T09:00')

export type Period = '7d' | '30d' | '90d'
export const PERIODS: { value: Period; label: string; days: number }[] = [
  { value: '7d', label: 'Last 7 days', days: 7 },
  { value: '30d', label: 'Last 30 days', days: 30 },
  { value: '90d', label: 'Last 90 days', days: 90 },
]

// A type, not an interface, so a row passes as a chart's data row.
export type DayTotals = {
  date: Date
  /** Hours the team logged that day. */
  hours: number
  /** Invoiced that day, in US dollars. */
  invoiced: number
}

/** One row a day for the 180 days up to the sample's today: twice the longest period, so each has a previous one to compare with. */
export const sampleDays: DayTotals[] = (() => {
  let seed = 32
  const r = () => ((seed = (seed * 16807) % 2147483647) - 1) / 2147483646
  return Array.from({ length: 180 }, (_, i) => {
    const date = new Date(sampleToday.getFullYear(), sampleToday.getMonth(), sampleToday.getDate() - 179 + i)
    const isWeekend = date.getDay() === 0 || date.getDay() === 6
    // A slow climb, so the latest period reads as growth.
    const trend = 1 + i / 400
    return {
      date,
      hours: isWeekend ? Math.round(r() * 6) : Math.round((48 + r() * 24) * trend),
      invoiced: isWeekend || r() < 0.55 ? 0 : Math.round((1500 + r() * 6000) * trend),
    }
  })
})()

export interface Task {
  id: string
  title: string
  /** The project it belongs to, shown under the title. */
  project: string
  due: Date
  isDone: boolean
}

/** The signed-in user's open work, soonest due first. */
export const sampleTasks: Task[] = [
  { id: 't1', title: 'Approve the Saltmarsh renewal quote', project: 'Saltmarsh Analytics', due: d('2026-09-29'), isDone: false },
  { id: 't2', title: 'Review the Harbor Lights sprint plan', project: 'Harbor Lights', due: d('2026-10-01'), isDone: false },
  { id: 't3', title: 'Send the Driftwood invoice reminder', project: 'Driftwood Docs', due: d('2026-10-02'), isDone: false },
  { id: 't4', title: 'Sign off the Granite Referral launch', project: 'Granite Referral', due: d('2026-10-06'), isDone: false },
]

export interface SetupStep {
  id: string
  /** What the step is, as the guide lists it. */
  label: string
  /** The button that does it, while it is the next step. */
  action: string
  isDone: boolean
}

/** Getting a new workspace ready; the guide shows until every step is done. */
export const sampleSetup: SetupStep[] = [
  { id: 'workspace', label: 'Name your workspace', action: 'Name workspace', isDone: true },
  { id: 'project', label: 'Create your first project', action: 'Create project', isDone: true },
  { id: 'team', label: 'Invite your team', action: 'Invite team', isDone: false },
  { id: 'calendar', label: 'Connect your calendar', action: 'Connect calendar', isDone: false },
]

import { Icon, type IconName } from '@/lib/icon'
import type { ReactNode } from 'react'
import { Tag, type TagVariant } from '../../atomic-elements/Tag'
import type { Project, ProjectActivity, ProjectHealth, ProjectStatus } from './projects-data'
import { Feed } from '../../patterns/application-ui/Feed'

/* Shared by the Projects and Project Detail templates: a project's status
   tag and its activity read the same on the list and on the record. */

export const statusTone: Record<ProjectStatus, TagVariant> = {
  Active: 'success',
  'On hold': 'neutral',
  Expired: 'danger',
  Inactive: 'neutral',
  'On grace period': 'warning',
}

/** Every status, in the order a picker lists them. */
export const STATUSES = Object.keys(statusTone) as ProjectStatus[]

export const healthLabel: Record<ProjectHealth, string> = { risk: 'Risk', 'potential-risk': 'Potential risk', 'on-track': 'On track' }
/** Every health, worst first, in the order a picker lists them. */
export const HEALTHS = Object.keys(healthLabel) as ProjectHealth[]

export const statusTag = (status: ProjectStatus) => <Tag size="sm" variant={statusTone[status]} text={status} />

export const fullMoment = new Intl.DateTimeFormat('en', { dateStyle: 'medium', timeStyle: 'short' })
export const money = new Intl.NumberFormat('en', { style: 'currency', currency: 'USD', notation: 'compact', maximumFractionDigits: 1 })

const activityIcon: Record<ProjectActivity['type'], IconName> = { created: 'plus', status: 'info', estimation: 'file' }

/** An event that names its project, for a list that spans several. */
export type ActivityEvent = ProjectActivity & { project?: string }

type ActivityTimelineProps = { className?: string } & (
  | { project: Project }
  /** Events across projects, as Home lists them: each names its project. The landmark around the list names it. */
  | { events: ActivityEvent[] }
)

/** What one event says after its author's name. */
function action(event: ActivityEvent): ReactNode {
  const of = event.project && (
    <>
      {' '}
      of <strong>{event.project}</strong>
    </>
  )
  switch (event.type) {
    case 'created':
      return event.project ? (
        <>
          created <strong>{event.project}</strong>
        </>
      ) : (
        'created the project'
      )
    case 'estimation':
      return (
        <>
          changed the estimation{of} from <strong>{money.format(event.from)}</strong> to <strong>{money.format(event.to)}</strong>
        </>
      )
    case 'status':
      return (
        <>
          changed the status{of} from {statusTag(event.from)} to {statusTag(event.to)}
        </>
      )
  }
}

/**
 * What happened, newest first, on the Feed pattern: one project's activity,
 * as the Projects row and the Project Detail aside show it (a region named
 * after the project), or events across projects, as Home shows them.
 */
export function ActivityTimeline({ className, ...props }: ActivityTimelineProps) {
  const [events, label]: [ActivityEvent[], string | undefined] =
    'project' in props ? [props.project.activity, `${props.project.name} activity`] : [props.events, undefined]
  return (
    <Feed
      role={label ? 'region' : undefined}
      aria-label={label}
      className={className}
      items={events.map((event) => ({
        media: <Icon name={activityIcon[event.type]} />,
        actor: event.by,
        action: action(event),
        at: event.at,
        comment: event.type === 'status' ? event.note : undefined,
      }))}
    />
  )
}
